const unrepliedOrchTask = `-- name: UnrepliedOrchTask :one
SELECT
    id, kind, from_node, from_key, from_label, to_node, to_key, body, reply_to,
    child_node, child_key, interaction, state, answered_by_node,
    answered_by_key, request_id, request_hash, created_at, updated_at
FROM orch_message
WHERE to_node = ? AND to_key = ? AND kind = 'task' AND state = 'delivered'
ORDER BY created_at DESC, id DESC
LIMIT 1
`

type UnrepliedOrchTaskParams struct {
	ToNode string
	ToKey  string
}

func (q *Queries) UnrepliedOrchTask(ctx context.Context, arg UnrepliedOrchTaskParams) (OrchMessage, error) {
	row := q.db.QueryRowContext(ctx, unrepliedOrchTask, arg.ToNode, arg.ToKey)
	var i OrchMessage
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.FromNode,
		&i.FromKey,
		&i.FromLabel,
		&i.ToNode,
		&i.ToKey,
		&i.Body,
		&i.ReplyTo,
		&i.ChildNode,
		&i.ChildKey,
		&i.Interaction,
		&i.State,
		&i.AnsweredByNode,
		&i.AnsweredByKey,
		&i.RequestID,
		&i.RequestHash,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
